CREATE DATABASE IF NOT EXISTS campus_events;
USE campus_events;
CREATE TABLE APP_USER(user_id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL,email VARCHAR(180) NOT NULL UNIQUE,phone VARCHAR(30),password_hash VARCHAR(255) NOT NULL,role VARCHAR(20) NOT NULL DEFAULT 'PARTICIPANT',CHECK(role IN ('ADMIN','ORGANIZER','PARTICIPANT')));
CREATE TABLE EVENT(event_id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(180) NOT NULL,type VARCHAR(80) NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'PLANNED',CHECK(end_date>=start_date),CHECK(status IN ('PLANNED','ACTIVE','COMPLETED','CANCELLED')));
CREATE TABLE VENUE(venue_id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL,capacity INT NOT NULL,location VARCHAR(180) NOT NULL,CHECK(capacity>0));
CREATE TABLE SESSION(session_id BIGINT PRIMARY KEY AUTO_INCREMENT,event_id BIGINT NOT NULL,title VARCHAR(180) NOT NULL,start_time DATETIME NOT NULL,end_time DATETIME NOT NULL,venue_id BIGINT NOT NULL,FOREIGN KEY(event_id) REFERENCES EVENT(event_id),FOREIGN KEY(venue_id) REFERENCES VENUE(venue_id),CHECK(end_time>start_time));
CREATE TABLE RESOURCE(resource_id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL,type VARCHAR(80) NOT NULL,quantity_total INT NOT NULL,location VARCHAR(180),CHECK(quantity_total>=0));
CREATE TABLE REGISTRATION(registration_id BIGINT PRIMARY KEY AUTO_INCREMENT,event_id BIGINT NOT NULL,user_id BIGINT NOT NULL,registration_date DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,status VARCHAR(20) NOT NULL DEFAULT 'REGISTERED',UNIQUE(event_id,user_id),FOREIGN KEY(event_id) REFERENCES EVENT(event_id),FOREIGN KEY(user_id) REFERENCES APP_USER(user_id),CHECK(status IN ('REGISTERED','CANCELLED','ATTENDED')));
CREATE TABLE PAYMENT(payment_id BIGINT PRIMARY KEY AUTO_INCREMENT,registration_id BIGINT NOT NULL,amount DECIMAL(10,2) NOT NULL,payment_date DATETIME DEFAULT CURRENT_TIMESTAMP,status VARCHAR(20) NOT NULL DEFAULT 'PENDING',FOREIGN KEY(registration_id) REFERENCES REGISTRATION(registration_id),CHECK(amount>=0),CHECK(status IN ('PENDING','PAID','FAILED','REFUNDED')));
CREATE TABLE RESOURCE_ALLOCATION(allocation_id BIGINT PRIMARY KEY AUTO_INCREMENT,event_id BIGINT NOT NULL,session_id BIGINT NULL,resource_id BIGINT NOT NULL,quantity INT NOT NULL,allocated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(event_id) REFERENCES EVENT(event_id),FOREIGN KEY(session_id) REFERENCES SESSION(session_id),FOREIGN KEY(resource_id) REFERENCES RESOURCE(resource_id),CHECK(quantity>0));
CREATE INDEX idx_session_venue_time ON SESSION(venue_id,start_time,end_time);
CREATE INDEX idx_registration_event ON REGISTRATION(event_id);
CREATE INDEX idx_allocation_resource ON RESOURCE_ALLOCATION(resource_id);